mapper.select:
select id, stat_date as statDate, member_id as memberId, candidate_type as candidateType,
       candidate_id as candidateId, score, reason_codes as reasonCodes,
       rank_position as rankPosition, create_time as createTime
from recommendation_score_daily

     and member_id = #{memberId}
     and candidate_type = #{candidateType}
     and candidate_id = #{candidateId}

order by stat_date desc, rank_position asc, score desc

select member_id as memberId, city_code as cityCode, category_weights_json as categoryWeightsJson
from member_interest_profile
where member_id > #{afterMemberId}
  and last_event_at >= #{activeSince}
order by member_id
limit #{limit}
